        public int Age_CustomerUpdUserInfo(int custId, string firstName, string lastName, string phone, string mobilePhone, string email, string fax, int synchronizedCasino, string ip, int userId, int subAccId, out string errorMsg)
        {
            errorMsg = string.Empty;
            Hashtable param = new Hashtable
            {
                {"custid", custId},
                {"firstname", firstName},
                {"lastname", lastName},
                {"phone", phone},
                {"mobilephone", mobilePhone},
                {"email", email},
                {"fax", fax},
                {"userid", userId},
                {"discasino", AppSettings.DisabledCasino},
                {"subaccid", subAccId},
                {"ip", ip},
                {"language", UserSession.Current.LangKey}
            };

            DbResult result = ExecSp("Age_CustomerUpdUserInfo", param);
            int errCode = Convert.ToInt32(result.Outputs["errorcode"]);
            errorMsg = result.Outputs["errormsg"].ToString();
            if (errCode <= 0)
            {
                if (synchronizedCasino == 1)
                {
                    Customer cust = new Customer();
                    try
                    {
                        cust.UpdateCustInfoSimpleNoStatus(custId, firstName, lastName, phone, mobilePhone, fax, email, AgentIPFormat.GetClientIP(), UserSession.Current.CustId, UserSession.Current.SubAccId == 0 ? UserSession.Current.UserName : UserSession.Current.SubUserName, 2);
                    }
                    catch { }
                }
            }

            return errCode;
        }

